/**
 * 도서산간 3개 탭을 심는다.
 * 주소사전은 사람이 채워 넣은 값이 들어 있으므로 없는 주소만 추가한다.
 */
function ss_도서산간심기() {
  var msg = [];

  ssio_write(SSIO_TABS.도서산간시군, SSM_ISL_KW_HEADER, SS_SEED_ISLAND_KW);
  msg.push('도서산간_시군 : ' + SS_SEED_ISLAND_KW.length + '행');

  ssio_write(SSIO_TABS.도서산간우편, SSM_ISL_ZIP_HEADER, SS_SEED_ISLAND_ZIP);
  var jeju = 0;
  for (var z = 0; z < SS_SEED_ISLAND_ZIP.length; z++) if (SS_SEED_ISLAND_ZIP[z][1] === '제주') jeju++;
  msg.push('도서산간_우편번호 : ' + SS_SEED_ISLAND_ZIP.length + '행 (제주 ' + jeju + ' / 도서 ' + (SS_SEED_ISLAND_ZIP.length - jeju) + ')');

  var sh = ssio_sheet(SSIO_TABS.도서산간사전, SSM_ISL_DICT_HEADER);
  var have = {};
  var body = ssio_body(SSIO_TABS.도서산간사전);
  for (var i = 0; i < body.length; i++) have[ssText(body[i][0])] = true;
  var add = [];
  var today = Utilities.formatDate(new Date(), 'Asia/Seoul', 'yyyy-MM-dd');
  for (var j = 0; j < SS_SEED_ISLAND_DICT.length; j++) {
    var d = SS_SEED_ISLAND_DICT[j];
    var a = ssNormAddr(d[0]);
    if (!a || have[a]) continue;
    have[a] = true;
    add.push([a, d[1], d[2], today, '구시트이관']);
  }
  if (add.length) sh.getRange(sh.getLastRow() + 1, 1, add.length, SSM_ISL_DICT_HEADER.length).setValues(add);
  msg.push('도서산간_주소사전 : ' + add.length + '행 추가 (기존 ' + body.length + '행 유지)');

  return ssio_alert('도서산간 목록 심기 완료\n\n  ' + msg.join('\n  '));
}
